// The consumer manifest (`bench_contract.yaml`, generated by `contract
// init`): which solution, which driver implements it and which scenarios it
// declares. Protocol values (runs, warm-ups, slack, timeouts) live in the
// package's methodology, NOT in the manifest — a consumer can pick
// scenarios but never redefine a metric.
import 'dart:io';

import 'package:yaml/yaml.dart';

import 'readme.dart';
import 'size.dart';

/// File name of the consumer manifest.
const String kManifestFileName = 'bench_contract.yaml';

/// Version of the generated templates (driver API + scenario files). Written
/// into the manifest by `init`; `contract verify` fails when the consumer's
/// generated files are older than the package's templates.
const int kTemplateVersion = 1;

/// All contract scenario ids (metric ids are identical to the scenario ids).
const Set<String> kContractScenarioIds = {
  'idle_zero',
  'idle_resources',
  'show_latency',
  'update_latency',
  'scroll_coupled',
  'active_heap',
  'hide_retention',
  'size',
};

/// Scenarios `init` enables by default (device-free runnable, no VM-service
/// requirement). The consumer adds heap scenarios + `size` when they apply.
const List<String> kDefaultScenarios = [
  'idle_zero',
  'show_latency',
  'update_latency',
  'scroll_coupled',
];

/// Runs per scenario in one `contract run` (methodology): the noisy
/// wall-latency metrics repeat and the report reducer takes the median;
/// heap scenarios already median internally; structural ones are
/// deterministic.
int runsForScenario(String scenarioId) =>
    scenarioId == 'show_latency' ? 3 : 1;

/// One consumer-owned scenario (`customScenarios:`): the metric id is
/// `custom.<name>` (package ids are reserved — shadowing a contract scenario
/// is rejected at load), it has its OWN golden ref, and it is excluded from
/// rivals comparison and public tables. The consumer writes the test (the
/// metric definition); the package provides the machinery (run, goldens,
/// gate) — the test reports `reportMetric('custom.<name>', value)` and the
/// CLI records/checks it under [ref].
class CustomScenario {
  const CustomScenario({
    required this.id,
    required this.name,
    required this.target,
    this.ref = 'custom',
    this.runs = 1,
  });

  /// Full metric/scenario id: `custom.<name>`.
  final String id;

  /// Short manifest key (`startup_to_show` → id `custom.startup_to_show`).
  final String name;

  /// Test file path, relative to the consumer root (consumer-authored).
  final String target;

  /// Golden ref of this scenario (own ref, e.g. `android-custom`).
  final String ref;

  /// Repeat count in one `contract run` (median-reduced like contract runs).
  final int runs;
}

/// Consumer-owned marketing content of the published metrics card PNG
/// (manifest `card:`; rendered by `contract card` from the recorded
/// goldens). The card MACHINERY (layout, value formatting, fonts, render
/// harness) is the package's — the consumer writes only the copy.
class CardConfig {
  const CardConfig({
    required this.title,
    required this.subtitle,
    required this.out,
    this.note,
    this.legend,
    this.subtitles = const {},
  });

  /// Header title (e.g. `hintful benchmarks — contract`).
  final String title;

  /// Header subtitle (the run description line).
  final String subtitle;

  /// PNG output path, relative to the consumer root.
  final String out;

  /// Methodology note in the last right tile slot.
  final String? note;

  /// Bottom legend text.
  final String? legend;

  /// Per-metric marketing line under each tile (metric key → subtitle).
  final Map<String, String> subtitles;
}

/// Consumer-owned marketing content of the root-README "Performance"
/// section (manifest `readme:`; rendered by `contract readme` from the
/// store). The consumer picks which solutions form the table columns and
/// writes the prose; the package renders rows/values with the canonical
/// defs (lib/defs.dart).
class ReadmeConfig {
  const ReadmeConfig({
    required this.target,
    required this.intro,
    required this.columns,
    required this.footnote,
    this.title = 'Performance',
    this.image,
    this.imageAlt,
    this.stamp,
  });

  /// README file path, relative to the consumer root.
  final String target;

  /// Heading text (`## Performance` by default).
  final String title;

  /// Prose paragraph under the heading.
  final String intro;

  /// Table columns (solution → golden refs), left to right.
  final List<ReadmeColumn> columns;

  /// Footnote under the table.
  final String footnote;

  /// Metrics-card image path, relative to [target]'s file.
  final String? image;

  /// Markdown alt text of [image].
  final String? imageAlt;

  /// Stamped line under the image; `{ts}` replaced at render time.
  final String? stamp;
}

/// One solution of a multi-library consumer (`libraries:` in the manifest).
/// Used by head-to-head consumers (e.g. the bench_compare package running
/// showcaseview + tutorial_coach_mark side by side): every entry gets its
/// own scenario directory and golden ref, sharing the scenario list.
class LibraryEntry {
  const LibraryEntry({
    required this.name,
    required this.driver,
    required this.driverClass,
    this.ref,
  });

  /// Solution name (report label, scenario directory name).
  final String name;

  /// Driver file path, relative to the consumer root.
  final String driver;

  /// Driver class name.
  final String driverClass;

  /// Golden ref override (e.g. `android-scv`); null → the CLI's --ref.
  final String? ref;
}

/// The consumer manifest.
class Manifest {
  Manifest({
    required this.library,
    required this.driver,
    required this.driverClass,
    required this.scenarios,
    this.contractDir = 'bench/contract',
    this.idleClasses = const [],
    this.libraries = const [],
    this.customScenarios = const [],
    this.template = kTemplateVersion,
    this.size,
    this.card,
    this.readme,
  });

  /// Solution name (report/README column label).
  final String library;

  /// Driver file path, relative to the consumer root (NOT under `lib/` — the
  /// driver runs in the flutter_test context and returns flutter_test types).
  final String driver;

  /// Driver class name (e.g. `HintfulDriver`).
  final String driverClass;

  /// Solutions of a multi-library consumer; empty for the single-library
  /// shape (library/driver/driverClass).
  final List<LibraryEntry> libraries;

  /// The solutions to run: declared libraries, or the single shape.
  List<LibraryEntry> get entries => libraries.isNotEmpty
      ? libraries
      : [
          LibraryEntry(
            name: library,
            driver: driver,
            driverClass: driverClass,
          ),
        ];

  /// Scenario directory of [entry]: the shared [contractDir] for the
  /// single-library shape, one subdirectory per solution otherwise.
  String dirFor(LibraryEntry entry) => libraries.isEmpty
      ? contractDir
      : '$contractDir/${entry.name}';

  /// Declared scenario ids (subset of [kContractScenarioIds]).
  final List<String> scenarios;

  /// Directory of the generated contract files (driver API + scenario
  /// tests), relative to the consumer root.
  final String contractDir;

  /// Solution classes that must return to their baseline after warm-up +
  /// `hide()` (S1r `idle_resources`).
  final List<String> idleClasses;

  /// Template version the generated files were rendered with.
  final int template;

  /// S7 host-size config (`size:` section); null when the consumer does not
  /// declare the size scenario.
  final SizeConfig? size;

  /// Marketing content of the metrics card PNG (`card:` section); null
  /// when the consumer does not publish a card.
  final CardConfig? card;

  /// Marketing content of the root-README section (`readme:` section); null
  /// when the consumer does not render one.
  final ReadmeConfig? readme;

  /// Consumer-owned scenarios (`customScenarios:`): metric ids
  /// `custom.*`, own refs, excluded from rivals and public tables.
  final List<CustomScenario> customScenarios;

  /// Loads the manifest from [root] (default: current directory).
  static Manifest load(String root) {
    final file = File('$root/$kManifestFileName');
    if (!file.existsSync()) {
      throw FileSystemException('no $kManifestFileName in $root — run '
          '"dart run flutter_bench_contract:contract init" first');
    }
    final dynamic doc;
    try {
      doc = loadYaml(file.readAsStringSync());
    } catch (e) {
      throw FormatException('cannot parse $kManifestFileName: $e');
    }
    if (doc is! YamlMap) {
      throw FormatException('$kManifestFileName: expected a YAML map');
    }
    String str(String key, {String fallback = ''}) =>
        (doc[key] as String?) ?? fallback;
    List<String> list(String key) =>
        [for (final s in (doc[key] as List? ?? const [])) s as String];

    // Multi-library shape: `libraries: {name: {driver, driverClass, ref?}}`.
    // When present it fully replaces the single-library fields (which may be
    // absent); the consumer runs each entry against the same scenario list.
    final librariesDoc = doc['libraries'];
    final libraries = <LibraryEntry>[];
    if (librariesDoc != null) {
      if (librariesDoc is! YamlMap) {
        throw FormatException('$kManifestFileName: libraries must be a map '
            '{name: {driver, driverClass, ref?}}');
      }
      for (final entry in librariesDoc.entries) {
        final name = entry.key as String;
        final spec = entry.value;
        if (spec is! YamlMap || spec['driver'] is! String ||
            spec['driverClass'] is! String) {
          throw FormatException('$kManifestFileName: libraries.$name needs '
              'driver + driverClass');
        }
        libraries.add(LibraryEntry(
          name: name,
          driver: spec['driver'] as String,
          driverClass: spec['driverClass'] as String,
          ref: spec['ref'] as String?,
        ));
      }
    }

    // Consumer-owned scenarios: keys are short names, the metric id is
    // `custom.<key>`; a key colliding with a contract scenario id is
    // shadowing and rejected (a package scenario cannot be redefined).
    final customScenarios = <CustomScenario>[];
    final customDoc = doc['customScenarios'];
    if (customDoc != null) {
      if (customDoc is! YamlMap) {
        throw FormatException('$kManifestFileName: customScenarios must be a '
            'map {name: {target, ref?, runs?}}');
      }
      for (final entry in customDoc.entries) {
        final name = entry.key as String;
        if (name.isEmpty || name.startsWith('custom.')) {
          throw FormatException('$kManifestFileName: customScenarios key '
              '"$name" must be a short name — the id is custom.<name>');
        }
        if (kContractScenarioIds.contains(name)) {
          throw FormatException('$kManifestFileName: customScenarios key '
              '"$name" shadows the contract scenario — package scenarios '
              'cannot be redefined');
        }
        final spec = entry.value;
        if (spec is! YamlMap || spec['target'] is! String ||
            (spec['target'] as String).isEmpty) {
          throw FormatException('$kManifestFileName: customScenarios.$name '
              'needs a non-empty target: (the test file path)');
        }
        final ref = spec['ref'] as String? ?? 'custom';
        if (ref.isEmpty) {
          throw FormatException('$kManifestFileName: customScenarios.$name '
              'ref must not be empty');
        }
        final runs = spec['runs'] is int ? spec['runs'] as int : 1;
        if (runs < 1) {
          throw FormatException('$kManifestFileName: customScenarios.$name '
              'runs must be >= 1');
        }
        customScenarios.add(CustomScenario(
          id: 'custom.$name',
          name: name,
          target: spec['target'] as String,
          ref: ref,
          runs: runs,
        ));
      }
    }

    // The contract `scenarios:` list holds only contract ids — a `custom.*`
    // entry there is a shape error (custom scenarios live under
    // `customScenarios:` and are not per-library).
    final scenarios = list('scenarios');
    for (final id in scenarios) {
      if (id.startsWith('custom.')) {
        throw FormatException('$kManifestFileName: scenario "$id" belongs '
            'under customScenarios:, not scenarios:');
      }
    }

    return Manifest(
      library: str('library'),
      driver: str('driver'),
      driverClass: str('driverClass'),
      contractDir: str('contractDir', fallback: 'bench/contract'),
      scenarios: scenarios,
      idleClasses: list('idleClasses'),
      libraries: libraries,
      customScenarios: customScenarios,
      template: doc['template'] is int ? doc['template'] as int : kTemplateVersion,
      size: SizeConfig.fromYaml(doc['size']),
      card: _cardFromYaml(doc['card']),
      readme: _readmeFromYaml(doc['readme']),
    );
  }

  /// `card:` section — optional; a malformed section is a hard error (the
  /// card machinery would silently render consumer garbage otherwise).
  static CardConfig? _cardFromYaml(Object? cardDoc) {
    if (cardDoc == null) return null;
    if (cardDoc is! YamlMap || cardDoc['title'] is! String ||
        cardDoc['subtitle'] is! String || cardDoc['out'] is! String) {
      throw FormatException('$kManifestFileName: card: needs title:,\n'
          'subtitle: and out: (the PNG path, relative to the consumer root)');
    }
    String? str(Object? v) => v is String ? v : null;
    final subtitles = <String, String>{};
    final subsDoc = cardDoc['subtitles'];
    if (subsDoc != null) {
      if (subsDoc is! YamlMap) {
        throw FormatException('$kManifestFileName: card.subtitles must be a '
            'map {metricKey: subtitle}');
      }
      for (final e in subsDoc.entries) {
        final key = e.key as String;
        if (e.value is! String) {
          throw FormatException('$kManifestFileName: card.subtitles.$key must '
              'be a string');
        }
        subtitles[key] = e.value as String;
      }
    }
    return CardConfig(
      title: cardDoc['title'] as String,
      subtitle: cardDoc['subtitle'] as String,
      out: cardDoc['out'] as String,
      note: str(cardDoc['note']),
      legend: str(cardDoc['legend']),
      subtitles: subtitles,
    );
  }

  /// `readme:` section — optional; a malformed section is a hard error.
  static ReadmeConfig? _readmeFromYaml(Object? readmeDoc) {
    if (readmeDoc == null) return null;
    if (readmeDoc is! YamlMap || readmeDoc['target'] is! String ||
        readmeDoc['intro'] is! String || readmeDoc['footnote'] is! String) {
      throw FormatException('$kManifestFileName: readme: needs target:,\n'
          'intro: and footnote: (the section copy); columns: lists the '
          'table columns {label, refs?, fallbackAny?}');
    }
    final columnsDoc = readmeDoc['columns'];
    if (columnsDoc is! YamlMap || columnsDoc.isEmpty) {
      throw FormatException('$kManifestFileName: readme.columns must be a '
          'non-empty map {label: {refs: [...], fallbackAny: bool}}');
    }
    final columns = <ReadmeColumn>[];
    for (final e in columnsDoc.entries) {
      final label = e.key as String;
      final spec = e.value;
      List<String> refs = const ['android', 'any'];
      var fallbackAny = true;
      if (spec is YamlMap) {
        final refsDoc = spec['refs'];
        if (refsDoc != null) {
          if (refsDoc is! List || refsDoc.isEmpty ||
              refsDoc.any((r) => r is! String)) {
            throw FormatException('$kManifestFileName: readme.columns.$label '
                'refs must be a non-empty list of strings');
          }
          refs = refsDoc.cast<String>();
        }
        fallbackAny = spec['fallbackAny'] is bool
            ? spec['fallbackAny'] as bool
            : true;
      }
      columns.add(ReadmeColumn(
        label: label,
        refs: refs,
        fallbackAny: fallbackAny,
      ));
    }
    String? str(Object? v) => v is String ? v : null;
    return ReadmeConfig(
      target: readmeDoc['target'] as String,
      title: str(readmeDoc['title']) ?? 'Performance',
      intro: readmeDoc['intro'] as String,
      columns: columns,
      footnote: readmeDoc['footnote'] as String,
      image: str(readmeDoc['image']),
      imageAlt: str(readmeDoc['imageAlt']),
      stamp: str(readmeDoc['stamp']),
    );
  }
}
